class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)


class ModelNew(nn.Module):
    """
    Optimized Grouped Query Attention using:
    1. Custom fused RoPE kernel 
    2. PyTorch's scaled_dot_product_attention with enable_gqa for efficient GQA
    """

    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        # Separate projections for Q, K, V
        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        # Rotary embeddings
        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

        self.fused_rope = fused_rope_module

    def repeat_kv(self, hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
        """Fallback KV expansion"""
        if n_rep == 1:
            return hidden_states
        batch, num_kv_heads, seq_len, head_dim = hidden_states.shape
        hidden_states = hidden_states[:, :, None, :, :].expand(
            batch, num_kv_heads, n_rep, seq_len, head_dim
        )
        return hidden_states.reshape(batch, num_kv_heads * n_rep, seq_len, head_dim)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # Project Q, K, V
        query_states = self.q_proj(hidden_states)
        key_states = self.k_proj(hidden_states)
        value_states = self.v_proj(hidden_states)

        # Reshape for multi-head attention
        query_states = query_states.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2).contiguous()
        key_states = key_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2).contiguous()
        value_states = value_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2).contiguous()

        # Apply rotary embeddings with fused kernel
        cos, sin = self.rotary_emb(value_states, seq_len=q_len)
        query_states, key_states = self.fused_rope.fused_rope_hip(query_states, key_states, cos, sin)

        # Expand KV heads to match query heads (required for standard attention)
        key_states = self.repeat_kv(key_states, self.num_key_value_groups)
        value_states = self.repeat_kv(value_states, self.num_key_value_groups)

        # Use scaled_dot_product_attention for efficient computation
        # It handles causal masking internally with is_causal=True
        attn_output = F.scaled_dot_product_attention(
            query_states,
            key_states, 
            value_states,
            attn_mask=None,
            dropout_p=self.attention_dropout if self.training else 0.0,
            is_causal=True,
            scale=self.softmax_scale
        )

        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.head_dim)

        # Output projection
        attn_output = self.o_proj(attn_output)

        return attn_output


def custom_kernel(inputs):
    hidden_states = inputs[0]

    # Use global config
    hidden_size = 4096
    num_attention_heads = 32
    num_key_value_heads = 8
    head_dim = 128
    max_position_embeddings = 4096

    model = ModelNew(
        hidden_size=hidden_size,
        num_attention_heads=num_attention_heads,
        num_key_value_heads=num_key_value_heads,
        head_dim=head_dim,
        max_position_embeddings=max_position_embeddings,
    ).to(hidden_states.device)

    return model(hidden_states)

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# HIP kernel for fused delta rule recurrence
deltanet_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Fused kernel for GatedDeltaNet recurrence
// S_t = alpha_t * S_{t-1} - beta_t * (S_{t-1} @ k_t - v_t) @ k_t^T
// o_t = S_t @ q_t
// 
// Each block handles one (batch, head) pair
// Threads within a block cooperate on the state matrix operations

__global__ void gated_deltanet_recurrence_kernel(
    const float* __restrict__ q,      // [batch, seq_len, num_heads, head_dim_qk]
    const float* __restrict__ k,      // [batch, seq_len, num_heads, head_dim_qk]
    const float* __restrict__ v,      // [batch, seq_len, num_heads, head_dim_v]
    const float* __restrict__ alpha,  // [batch, seq_len, num_heads]
    const float* __restrict__ beta,   // [batch, seq_len, num_heads]
    float* __restrict__ output,       // [batch, seq_len, num_heads, head_dim_v]
    int batch_size,
    int seq_len,
    int num_heads,
    int head_dim_qk,
    int head_dim_v
) {
    // Each block handles one (batch, head) pair
    int batch_idx = blockIdx.x / num_heads;
    int head_idx = blockIdx.x % num_heads;

    if (batch_idx >= batch_size) return;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // State matrix S: [head_dim_v, head_dim_qk]
    // Each thread handles a subset of the state matrix elements
    extern __shared__ float shared_mem[];
    float* S = shared_mem;  // [head_dim_v * head_dim_qk]
    float* S_k = S + head_dim_v * head_dim_qk;  // [head_dim_v] - result of S @ k
    float* k_shared = S_k + head_dim_v;  // [head_dim_qk]
    float* v_shared = k_shared + head_dim_qk;  // [head_dim_v]
    float* q_shared = v_shared + head_dim_v;  // [head_dim_qk]

    int state_size = head_dim_v * head_dim_qk;

    // Initialize state to zero
    for (int i = tid; i < state_size; i += num_threads) {
        S[i] = 0.0f;
    }
    __syncthreads();

    // Loop over sequence
    for (int t = 0; t < seq_len; t++) {
        // Load k, v, q for this timestep
        int base_qk = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_qk;
        int base_v = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_v;
        int base_gate = (batch_idx * seq_len + t) * num_heads + head_idx;

        // Load k into shared memory
        for (int i = tid; i < head_dim_qk; i += num_threads) {
            k_shared[i] = k[base_qk + i];
        }
        // Load v into shared memory
        for (int i = tid; i < head_dim_v; i += num_threads) {
            v_shared[i] = v[base_v + i];
        }
        // Load q into shared memory
        for (int i = tid; i < head_dim_qk; i += num_threads) {
            q_shared[i] = q[base_qk + i];
        }
        __syncthreads();

        float alpha_t = alpha[base_gate];
        float beta_t = beta[base_gate];

        // Compute S @ k -> S_k [head_dim_v]
        // Each thread computes some rows
        for (int i = tid; i < head_dim_v; i += num_threads) {
            float sum = 0.0f;
            for (int j = 0; j < head_dim_qk; j++) {
                sum += S[i * head_dim_qk + j] * k_shared[j];
            }
            S_k[i] = sum;
        }
        __syncthreads();

        // Compute error = S_k - v and update S
        // S_ij = alpha * S_ij - beta * error_i * k_j
        // where error_i = S_k_i - v_i
        for (int idx = tid; idx < state_size; idx += num_threads) {
            int i = idx / head_dim_qk;  // v dimension
            int j = idx % head_dim_qk;  // k dimension

            float error_i = S_k[i] - v_shared[i];
            S[idx] = alpha_t * S[idx] - beta_t * error_i * k_shared[j];
        }
        __syncthreads();

        // Compute output: o = S @ q -> [head_dim_v]
        int out_base = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_v;
        for (int i = tid; i < head_dim_v; i += num_threads) {
            float sum = 0.0f;
            for (int j = 0; j < head_dim_qk; j++) {
                sum += S[i * head_dim_qk + j] * q_shared[j];
            }
            output[out_base + i] = sum;
        }
        __syncthreads();
    }
}

torch::Tensor gated_deltanet_recurrence(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor alpha,
    torch::Tensor beta
) {
    int batch_size = q.size(0);
    int seq_len = q.size(1);
    int num_heads = q.size(2);
    int head_dim_qk = q.size(3);
    int head_dim_v = v.size(3);

    auto output = torch::zeros({batch_size, seq_len, num_heads, head_dim_v}, 
                               q.options());

    // Ensure contiguous
    q = q.contiguous();
    k = k.contiguous();
    v = v.contiguous();
    alpha = alpha.contiguous();
    beta = beta.contiguous();

    int num_blocks = batch_size * num_heads;
    int threads_per_block = 256;

    // Shared memory: S + S_k + k + v + q
    int shared_mem_size = (head_dim_v * head_dim_qk + head_dim_v + head_dim_qk + head_dim_v + head_dim_qk) * sizeof(float);

    hipLaunchKernelGGL(gated_deltanet_recurrence_kernel, 
                       dim3(num_blocks), dim3(threads_per_block), shared_mem_size, 0,
                       q.data_ptr<float>(),
                       k.data_ptr<float>(),
                       v.data_ptr<float>(),
                       alpha.data_ptr<float>(),
                       beta.data_ptr<float>(),
                       output.data_ptr<float>(),
                       batch_size, seq_len, num_heads, head_dim_qk, head_dim_v);

    return output;
}

