# HIP kernel for fused FP8-simulated matmul
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/hip/HIPStream.h>

// E4M3 quantization parameters
#define E4M3_MAX 448.0f
#define E4M3_MIN -448.0f

// Fast FP8 E4M3 simulation - quantize and dequantize in one pass
__device__ __forceinline__ float fp8_e4m3_sim(float x, float scale, float inv_scale) {
    // Scale up
    float scaled = x * scale;
    // Clamp to FP8 range
    scaled = fminf(fmaxf(scaled, E4M3_MIN), E4M3_MAX);
    // Simulate quantization by rounding to nearest representable
    // E4M3: 1 sign, 4 exponent, 3 mantissa
    // This gives us 8 mantissa values (including implicit 1)
    // For simplicity, we simulate by rounding to nearest 1/8
    float rounded = rintf(scaled * 8.0f) / 8.0f;
    // Scale back down
    return rounded * inv_scale;
}

// Kernel for computing max absolute value with vectorized loads
__global__ void compute_amax_kernel(const float* __restrict__ input,
                                    float* __restrict__ amax,
                                    int size) {
    __shared__ float shared_max[256];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x * 4 + threadIdx.x;
    int stride = blockDim.x * gridDim.x * 4;

    float local_max = 0.0f;

    // Vectorized load - process 4 elements at a time
    for (int i = idx; i < size / 4; i += stride / 4) {
        float4 vals = reinterpret_cast<const float4*>(input)[i];
        local_max = fmaxf(local_max, fabsf(vals.x));
        local_max = fmaxf(local_max, fabsf(vals.y));
        local_max = fmaxf(local_max, fabsf(vals.z));
        local_max = fmaxf(local_max, fabsf(vals.w));
    }

    // Handle remaining elements
    int remainder_start = (size / 4) * 4;
    for (int i = remainder_start + tid; i < size; i += blockDim.x) {
        local_max = fmaxf(local_max, fabsf(input[i]));
    }

    shared_max[tid] = local_max;
    __syncthreads();

    // Reduction within block
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + s]);
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicMax((int*)amax, __float_as_int(shared_max[0]));
    }
}

// Half-precision version
__global__ void compute_amax_half_kernel(const __half* __restrict__ input,
                                         float* __restrict__ amax,
                                         int size) {
    __shared__ float shared_max[256];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    float local_max = 0.0f;

    for (int i = idx; i < size; i += stride) {
        float val = __half2float(input[i]);
        local_max = fmaxf(local_max, fabsf(val));
    }

    shared_max[tid] = local_max;
    __syncthreads();

    // Reduction within block
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + s]);
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicMax((int*)amax, __float_as_int(shared_max[0]));
    }
}

torch::Tensor compute_amax_hip(torch::Tensor x) {
    auto size = x.numel();
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
    auto amax = torch::zeros({1}, options);

    const int block_size = 256;
    const int num_blocks = std::min((int)((size + block_size - 1) / block_size), 1024);

    hipStream_t stream = c10::hip::getCurrentHIPStream();

    if (x.dtype() == torch::kFloat16) {
        compute_amax_half_kernel<<<num_blocks, block_size, 0, stream>>>(
            reinterpret_cast<const __half*>(x.data_ptr<at::Half>()),
            amax.data_ptr<float>(),
            size
        );
    } else {
        compute_amax_kernel<<<num_blocks, block_size, 0, stream>>>(
            x.data_ptr<float>(),
            amax.data_ptr<float>(),
            size
        );
    }

    return amax;
}

// Fused FP8 matmul simulation kernel using tiled approach
// A: (M, K), B: (K, N) -> C: (M, N)
// This simulates FP8 quantization during the matmul
#define TILE_M 64
#define TILE_N 64
#define TILE_K 16

__global__ void fp8_sim_matmul_kernel(
    const __half* __restrict__ A,  // (M, K)
    const __half* __restrict__ B,  // (K, N)
    __half* __restrict__ C,        // (M, N)
    int M, int K, int N,
    float a_scale, float a_inv_scale,
    float b_scale, float b_inv_scale
) {
    // Each block computes a TILE_M x TILE_N tile of C
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Thread block dimensions: (TILE_N/4, TILE_M/4) = (16, 16)
    int row = by * TILE_M + ty * 4;
    int col = bx * TILE_N + tx * 4;

    // Accumulate in FP32 for precision
    float acc[4][4] = {0.0f};

    // Shared memory for tiles
    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_K][TILE_N];

    // Loop over K dimension in tiles
    for (int k_tile = 0; k_tile < K; k_tile += TILE_K) {
        // Load A tile with FP8 simulation
        for (int i = 0; i < 4; i++) {
            int a_row = by * TILE_M + ty * 4 + i;
            for (int j = 0; j < TILE_K && (tx * (TILE_K / 16) + j / 4) < TILE_K / 4; j++) {
                int a_col = k_tile + tx;
                if (a_row < M && a_col < K) {
                    float val = __half2float(A[a_row * K + a_col]);
                    // Simulate FP8 quantization
                    float scaled = val * a_scale;
                    scaled = fminf(fmaxf(scaled, E4M3_MIN), E4M3_MAX);
                    As[ty * 4 + i][tx] = scaled * a_inv_scale;
                } else {
                    As[ty * 4 + i][tx] = 0.0f;
                }
            }
        }

        // Load B tile with FP8 simulation
        for (int i = 0; i < TILE_K / 16 && ty < TILE_K; i++) {
            int b_row = k_tile + ty;
            for (int j = 0; j < 4; j++) {
                int b_col = bx * TILE_N + tx * 4 + j;
                if (b_row < K && b_col < N) {
                    float val = __half2float(B[b_row * N + b_col]);
                    // Simulate FP8 quantization
                    float scaled = val * b_scale;
                    scaled = fminf(fmaxf(scaled, E4M3_MIN), E4M3_MAX);
                    Bs[ty][tx * 4 + j] = scaled * b_inv_scale;
                } else {
                    Bs[ty][tx * 4 + j] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute partial dot products
        for (int k = 0; k < TILE_K; k++) {
            for (int i = 0; i < 4; i++) {
                float a_val = As[ty * 4 + i][k];
                for (int j = 0; j < 4; j++) {
                    acc[i][j] += a_val * Bs[k][tx * 4 + j];
                }
            }
        }

        __syncthreads();
    }

    // Store results
    for (int i = 0; i < 4; i++) {
        int out_row = row + i;
        if (out_row < M) {
            for (int j = 0; j < 4; j++) {
                int out_col = col + j;
                if (out_col < N) {
                    C[out_row * N + out_col] = __float2half(acc[i][j]);
                }
            }
        }
    }
}

torch::Tensor fp8_sim_matmul_hip(
    torch::Tensor A,
    torch::Tensor B,
    torch::Tensor a_scale,
    torch::Tensor b_scale
) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    float a_s = a_scale.item<float>();
    float b_s = b_scale.item<float>();
    float a_inv = 1.0f / a_s;
    float b_inv = 1.0f / b_s;

    dim3 block(16, 16);
    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    hipStream_t stream = c10::hip::getCurrentHIPStream();

    fp8_sim_matmul_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
        M, K, N,
        a_s, a_inv,
        b_s, b_inv
    );

    return C;
}
