# Fused KDA recurrence kernel with optimizations
kda_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define WARP_SIZE 64
#define MAX_DIM 128

// Optimized KDA state update kernel
// Uses warp-level operations for better efficiency
__global__ void kda_recurrence_kernel_v2(
    const float* __restrict__ q,      // (batch, seq, heads, head_dim_qk)
    const float* __restrict__ k,      // (batch, seq, heads, head_dim_qk)
    const float* __restrict__ v,      // (batch, seq, heads, head_dim_v)
    const float* __restrict__ a,      // (batch, seq, heads, head_dim_v)
    const float* __restrict__ beta,   // (batch, seq, heads)
    float* __restrict__ output,       // (batch, seq, heads, head_dim_v)
    int batch_size,
    int seq_len,
    int num_heads,
    int head_dim_qk,
    int head_dim_v
) {
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // Shared memory
    extern __shared__ float shared_mem[];
    float* k_shared = shared_mem;
    float* q_shared = shared_mem + head_dim_qk;
    float* v_shared = shared_mem + 2 * head_dim_qk;
    float* a_shared = shared_mem + 2 * head_dim_qk + head_dim_v;
    float* Sk_shared = shared_mem + 2 * head_dim_qk + 2 * head_dim_v;

    // Each thread maintains state for multiple rows
    // For head_dim_v=128, head_dim_qk=128, and 128 threads:
    // Thread i handles row i
    float S_row[MAX_DIM];  // State row for this thread

    // Initialize
    #pragma unroll 4
    for (int c = 0; c < head_dim_qk; c++) {
        S_row[c] = 0.0f;
    }

    // Base offsets for this (batch, head) pair
    int stride_seq_qk = num_heads * head_dim_qk;
    int stride_seq_v = num_heads * head_dim_v;
    int stride_seq_beta = num_heads;

    int base_qk = batch_idx * seq_len * stride_seq_qk + head_idx * head_dim_qk;
    int base_v = batch_idx * seq_len * stride_seq_v + head_idx * head_dim_v;
    int base_beta = batch_idx * seq_len * stride_seq_beta + head_idx;

    // Process sequence
    for (int t = 0; t < seq_len; t++) {
        int off_qk = base_qk + t * stride_seq_qk;
        int off_v = base_v + t * stride_seq_v;
        int off_beta = base_beta + t * stride_seq_beta;

        // Load k, q, v, a into shared memory (coalesced access)
        if (tid < head_dim_qk) {
            k_shared[tid] = k[off_qk + tid];
            q_shared[tid] = q[off_qk + tid];
        }
        if (tid < head_dim_v) {
            v_shared[tid] = v[off_v + tid];
            a_shared[tid] = a[off_v + tid];
        }
        __syncthreads();

        float beta_t = beta[off_beta];

        // Each thread computes S @ k for its row
        if (tid < head_dim_v) {
            float dot = 0.0f;
            #pragma unroll 8
            for (int c = 0; c < head_dim_qk; c++) {
                dot += S_row[c] * k_shared[c];
            }
            Sk_shared[tid] = dot;
        }
        __syncthreads();

        // Update state row: S[row,:] = a[row] * S[row,:] - beta * (Sk[row] - v[row]) * k[:]
        if (tid < head_dim_v) {
            float a_r = a_shared[tid];
            float error = Sk_shared[tid] - v_shared[tid];
            float coeff = beta_t * error;

            #pragma unroll 8
            for (int c = 0; c < head_dim_qk; c++) {
                S_row[c] = a_r * S_row[c] - coeff * k_shared[c];
            }
        }
        __syncthreads();

        // Output: o[row] = S[row,:] @ q
        if (tid < head_dim_v) {
            float dot = 0.0f;
            #pragma unroll 8
            for (int c = 0; c < head_dim_qk; c++) {
                dot += S_row[c] * q_shared[c];
            }
            output[off_v + tid] = dot;
        }
        __syncthreads();
    }
}

torch::Tensor kda_recurrence_hip(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor a,
    torch::Tensor beta
) {
    auto batch_size = q.size(0);
    auto seq_len = q.size(1);
    auto num_heads = q.size(2);
    auto head_dim_qk = q.size(3);
    auto head_dim_v = v.size(3);

    auto output = torch::zeros_like(v);

    dim3 grid(batch_size, num_heads);
    int block_size = 128;  // Match head_dim_v

    // Shared memory size
    int shared_mem_size = (2 * head_dim_qk + 3 * head_dim_v) * sizeof(float);

    kda_recurrence_kernel_v2<<<grid, block_size, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        a.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        seq_len,
        num_heads,
        head_dim_qk,
        head_dim_v
    );

    return output;
}
"""

