# Highly optimized KDA recurrence kernel with vectorized loads
kda_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define WARP_SIZE 64
#define MAX_DIM 128
#define VECTOR_SIZE 4

// Vectorized float4 load/store
typedef float4 vec4;

__device__ __forceinline__ vec4 load_vec4(const float* ptr) {
    return *reinterpret_cast<const vec4*>(ptr);
}

__device__ __forceinline__ void store_vec4(float* ptr, vec4 val) {
    *reinterpret_cast<vec4*>(ptr) = val;
}

// Highly optimized KDA kernel
__global__ void kda_recurrence_kernel_v3(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ v,
    const float* __restrict__ a,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch_size,
    int seq_len,
    int num_heads,
    int head_dim_qk,
    int head_dim_v
) {
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // Shared memory
    extern __shared__ float shared_mem[];
    float* k_shared = shared_mem;
    float* q_shared = shared_mem + head_dim_qk;
    float* v_shared = shared_mem + 2 * head_dim_qk;
    float* a_shared = shared_mem + 2 * head_dim_qk + head_dim_v;
    float* Sk_shared = shared_mem + 2 * head_dim_qk + 2 * head_dim_v;

    // Each thread handles one row of S (head_dim_v=128, 128 threads)
    // Store state in registers
    float S_row[MAX_DIM];

    // Initialize state to zero using pragma unroll
    #pragma unroll
    for (int c = 0; c < 128; c++) {
        S_row[c] = 0.0f;
    }

    // Strides
    int stride_seq_qk = num_heads * head_dim_qk;
    int stride_seq_v = num_heads * head_dim_v;
    int stride_seq_beta = num_heads;

    int base_qk = batch_idx * seq_len * stride_seq_qk + head_idx * head_dim_qk;
    int base_v = batch_idx * seq_len * stride_seq_v + head_idx * head_dim_v;
    int base_beta = batch_idx * seq_len * stride_seq_beta + head_idx;

    // Process sequence
    for (int t = 0; t < seq_len; t++) {
        int off_qk = base_qk + t * stride_seq_qk;
        int off_v = base_v + t * stride_seq_v;
        int off_beta = base_beta + t * stride_seq_beta;

        // Load k, q, v, a into shared memory
        // Use vectorized loads where possible (assuming alignment)
        if (tid < head_dim_qk) {
            k_shared[tid] = k[off_qk + tid];
            q_shared[tid] = q[off_qk + tid];
        }
        if (tid < head_dim_v) {
            v_shared[tid] = v[off_v + tid];
            a_shared[tid] = a[off_v + tid];
        }
        __syncthreads();

        float beta_t = beta[off_beta];

        // Compute S @ k for row tid
        if (tid < head_dim_v) {
            float dot = 0.0f;
            // Unroll by 8 for better ILP
            #pragma unroll 16
            for (int c = 0; c < 128; c++) {
                dot += S_row[c] * k_shared[c];
            }
            Sk_shared[tid] = dot;
        }
        __syncthreads();

        // Update and compute output
        if (tid < head_dim_v) {
            float a_r = a_shared[tid];
            float error = Sk_shared[tid] - v_shared[tid];
            float coeff = beta_t * error;

            float out_dot = 0.0f;

            #pragma unroll 16
            for (int c = 0; c < 128; c++) {
                // Update state
                S_row[c] = a_r * S_row[c] - coeff * k_shared[c];
                // Compute output at same time
                out_dot += S_row[c] * q_shared[c];
            }

            output[off_v + tid] = out_dot;
        }
        __syncthreads();
    }
}

torch::Tensor kda_recurrence_hip(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor a,
