        int cs_idx1 = s * head_dim + d;
        int cs_idx2 = s * head_dim + d + half_dim;

        float cos1 = cos[cs_idx1];
        float sin1 = sin[cs_idx1];
        float cos2 = cos[cs_idx2];
        float sin2 = sin[cs_idx2];

        float x1 = k_in[idx1];
        float x2 = k_in[idx2];

        k_out[idx1] = x1 * cos1 + (-x2) * sin1;
        k_out[idx2] = x2 * cos2 + x1 * sin2;
    }
