os.environ["CXX"] = "hipcc"

hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <torch/extension.h>

// Fused INT4 unpack + dequantize + GEMM kernel
// X: (M, K) float16
// weight_packed: (N, K/2) uint8
// scales: (N, num_groups) float16
// output: (M, N) float16
__global__ void int4_gemm_kernel(
    const __half* __restrict__ X,
    const uint8_t* __restrict__ weight_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ output,
    int M, int N, int K, int group_size, int num_groups
) {
    // Each thread computes one output element
    int row = blockIdx.y * blockDim.y + threadIdx.y;  // M dimension
    int col = blockIdx.x * blockDim.x + threadIdx.x;  // N dimension

    if (row >= M || col >= N) return;

    float acc = 0.0f;
    int K_half = K / 2;

    // Process all K elements
    for (int k = 0; k < K; k += 2) {
        // Load packed byte containing 2 INT4 weights
        int byte_idx = k / 2;
        uint8_t packed_byte = weight_packed[col * K_half + byte_idx];

        // Unpack INT4 values
        int w0 = packed_byte & 0x0F;        // low nibble (first weight)
        int w1 = (packed_byte >> 4) & 0x0F; // high nibble (second weight)

        // Get scales for this group
        int g0 = k / group_size;
        int g1 = (k + 1) / group_size;

        float scale0 = __half2float(scales[col * num_groups + g0]);
        float scale1 = __half2float(scales[col * num_groups + g1]);

        // Dequantize: scale * (w - 8)
        float w_dequant0 = scale0 * (float)(w0 - 8);
        float w_dequant1 = scale1 * (float)(w1 - 8);

        // Load X values
        float x0 = __half2float(X[row * K + k]);
        float x1 = __half2float(X[row * K + k + 1]);

        // Accumulate
        acc += x0 * w_dequant0 + x1 * w_dequant1;
    }

    output[row * N + col] = __float2half(acc);
}

torch::Tensor int4_gemm_hip(
    torch::Tensor X,
    torch::Tensor weight_packed,
    torch::Tensor scales,
    int group_size
) {
    int M = X.size(0);
    int K = X.size(1);
    int N = weight_packed.size(0);
    int num_groups = scales.size(1);

    auto output = torch::empty({M, N}, X.options());

    // Use 2D grid for better parallelism
    dim3 block(16, 16);
    dim3 grid((N + 15) / 16, (M + 15) / 16);

    int4_gemm_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(X.data_ptr<at::Half>()),
        weight_packed.data_ptr<uint8_t>(),
        reinterpret_cast<const __half*>(scales.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        M, N, K, group_size, num_groups
    );

    return output;
}
"""

