# Optimized KDA kernel using 256 threads with 2 threads per row
kda_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define WARP_SIZE 64
#define MAX_DIM 128

// Use 256 threads: 2 warps handle each half of the row
__global__ void kda_recurrence_kernel_v5(
    const float* __restrict__ q,
    const float* __restrict__ k,
    const float* __restrict__ v,
    const float* __restrict__ a,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch_size,
    int seq_len,
    int num_heads,
    int head_dim_qk,
    int head_dim_v
) {
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    int tid = threadIdx.x;

    // Shared memory
    extern __shared__ float shared_mem[];
    float* k_shared = shared_mem;                          // head_dim_qk (128)
    float* q_shared = shared_mem + 128;                    // head_dim_qk (128)
    float* v_shared = shared_mem + 256;                    // head_dim_v (128)
    float* a_shared = shared_mem + 384;                    // head_dim_v (128)
    float* Sk_shared = shared_mem + 512;                   // head_dim_v (128)

    // 256 threads, 128 rows -> 2 threads per row
    // Thread tid handles row (tid % 128)
    // Threads 0-127 handle cols 0-63, threads 128-255 handle cols 64-127
    int row = tid % 128;
    int col_offset = (tid >= 128) ? 64 : 0;

    // Each thread handles half of a row (64 elements)
    float S_half[64];
    #pragma unroll
    for (int c = 0; c < 64; c++) {
        S_half[c] = 0.0f;
    }

    // Strides
    int stride_seq_qk = num_heads * 128;  // head_dim_qk = 128
    int stride_seq_v = num_heads * 128;   // head_dim_v = 128
    int stride_seq_beta = num_heads;

    int base_qk = batch_idx * seq_len * stride_seq_qk + head_idx * 128;
    int base_v = batch_idx * seq_len * stride_seq_v + head_idx * 128;
    int base_beta = batch_idx * seq_len * stride_seq_beta + head_idx;

    // Process sequence
    for (int t = 0; t < seq_len; t++) {
        int off_qk = base_qk + t * stride_seq_qk;
        int off_v = base_v + t * stride_seq_v;
        int off_beta = base_beta + t * stride_seq_beta;

        // Load k, q, v, a into shared memory
        if (tid < 128) {
            k_shared[tid] = k[off_qk + tid];
            q_shared[tid] = q[off_qk + tid];
            v_shared[tid] = v[off_v + tid];
            a_shared[tid] = a[off_v + tid];
        }
        __syncthreads();

        float beta_t = beta[off_beta];

        // Compute S @ k for this half-row
        float partial_dot = 0.0f;
        #pragma unroll 8
        for (int c = 0; c < 64; c++) {
            partial_dot += S_half[c] * k_shared[col_offset + c];
        }

        // Reduce across the two threads handling same row
        // Thread tid and tid+128 (or tid-128) handle same row
        // Use shared memory for reduction
        if (tid < 128) {
            Sk_shared[tid] = partial_dot;
        }
        __syncthreads();

        if (tid >= 128) {
            // Second half adds to first half result
            atomicAdd(&Sk_shared[row], partial_dot);
        }
        __syncthreads();

        // Update state
        float a_r = a_shared[row];
        float error = Sk_shared[row] - v_shared[row];
        float coeff = beta_t * error;

        #pragma unroll 8
        for (int c = 0; c < 64; c++) {
            S_half[c] = a_r * S_half[c] - coeff * k_shared[col_offset + c];
        }
        __syncthreads();

        // Output: o[row] = S[row,:] @ q - need reduction again
        float partial_out = 0.0f;
        #pragma unroll 8
        for (int c = 0; c < 64; c++) {
            partial_out += S_half[c] * q_shared[col_offset + c];
        }

        if (tid < 128) {
            Sk_shared[tid] = partial_out;
        }
        __syncthreads();

        if (tid >= 128) {
            atomicAdd(&Sk_shared[row], partial_out);
        }
        __syncthreads();

        // Write output
        if (tid < 128) {
            output[off_v + tid] = Sk_shared[tid];
        }
        __syncthreads();
    }
}

torch::Tensor kda_recurrence_hip(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor a,
    torch::Tensor beta
) {
    auto batch_size = q.size(0);
    auto seq_len = q.size(1);
    auto num_heads = q.size(2);
    auto head_dim_qk = q.size(3);
    auto head_dim_v = v.size(3);

    auto output = torch::zeros_like(v);

    dim3 grid(batch_size, num_heads);
    int block_size = 256;

    int shared_mem_size = (128 * 5) * sizeof(float);  // k, q, v, a, Sk

    kda_recurrence_kernel_v5<<<grid, block_size, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        a.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        seq_len,
        num_heads,
        head_dim_qk,
        head_dim_v
    );

    return output;
}
"""

