# Fused RMSNorm + optional Linear kernel
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = 32 / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__device__ __forceinline__ float blockReduceSum(float val) {
    __shared__ float shared[32];
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0.0f;
    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void rmsnorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int hidden_size,
    int num_rows,
    float eps
) {
    int row = blockIdx.x;
    if (row >= num_rows) return;

    const float* row_input = input + row * hidden_size;
    float* row_output = output + row * hidden_size;

    float local_sum = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = row_input[i];
        local_sum += val * val;
    }

    float sum = blockReduceSum(local_sum);

    __shared__ float s_rsqrt;
    if (threadIdx.x == 0) {
        s_rsqrt = rsqrtf(sum / hidden_size + eps);
    }
    __syncthreads();

    float rsqrt_var = s_rsqrt;

    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        row_output[i] = row_input[i] * rsqrt_var * weight[i];
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor input, torch::Tensor weight, float eps) {
    auto input_cont = input.contiguous();
    auto output = torch::empty_like(input_cont);
    int hidden_size = input_cont.size(-1);
    int num_rows = input_cont.numel() / hidden_size;

    int block_size = 256;
    rmsnorm_kernel<<<num_rows, block_size>>>(
        input_cont.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        num_rows,
        eps
    );

    return output;
}

// Fused RoPE application kernel
__global__ void apply_rope_inplace_kernel(
    float* __restrict__ q,       // [batch, heads, seq, dim]
    float* __restrict__ k,       // [batch, 1, seq, dim]
    const float* __restrict__ cos,  // [seq, dim]
    const float* __restrict__ sin,  // [seq, dim]
    int batch_size,
    int num_heads,
    int seq_len,
    int dim
) {
    // Process q
    int total_q = batch_size * num_heads * seq_len * dim;
    int half_dim = dim / 2;

    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total_q; idx += blockDim.x * gridDim.x) {
        int d = idx % dim;
        int s = (idx / dim) % seq_len;
        int base = idx - d;

        float c = cos[s * dim + d];
        float sn = sin[s * dim + d];
        float val = q[idx];
        float rot = (d < half_dim) ? -q[base + d + half_dim] : q[base + d - half_dim];
        q[idx] = val * c + rot * sn;
    }

    // Process k (1 head)
    int total_k = batch_size * seq_len * dim;
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total_k; idx += blockDim.x * gridDim.x) {
        int d = idx % dim;
        int s = (idx / dim) % seq_len;
        int base = idx - d;

        float c = cos[s * dim + d];
        float sn = sin[s * dim + d];
        float val = k[idx];
        float rot = (d < half_dim) ? -k[base + d + half_dim] : k[base + d - half_dim];
        k[idx] = val * c + rot * sn;
    }
}

void apply_rope_inplace_hip(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor cos,
    torch::Tensor sin
) {
    int batch_size = q.size(0);
    int num_heads = q.size(1);
    int seq_len = q.size(2);
    int dim = q.size(3);

    int total = batch_size * num_heads * seq_len * dim;
    int block_size = 256;
    int num_blocks = (total + block_size - 1) / block_size;

    apply_rope_inplace_kernel<<<num_blocks, block_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        dim
    );
}
"""

