import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# C++ header for function declarations
deltanet_cpp_source = """
#include <torch/extension.h>

torch::Tensor gated_deltanet_recurrence(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor alpha,
    torch::Tensor beta
);
"""

# Optimized HIP kernel - better cache line utilization and fewer shared memory accesses
deltanet_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Optimized kernel with 2D thread block for better parallelism
// Block structure: (head_dim_v, head_dim_qk / elements_per_thread)
__global__ void gated_deltanet_recurrence_kernel(
    const float* __restrict__ q,      // [batch, seq_len, num_heads, head_dim_qk]
    const float* __restrict__ k,      // [batch, seq_len, num_heads, head_dim_qk]
    const float* __restrict__ v,      // [batch, seq_len, num_heads, head_dim_v]
    const float* __restrict__ alpha,  // [batch, seq_len, num_heads]
    const float* __restrict__ beta,   // [batch, seq_len, num_heads]
    float* __restrict__ output,       // [batch, seq_len, num_heads, head_dim_v]
    float* __restrict__ state,        // [batch, num_heads, head_dim_v, head_dim_qk]
    int batch_size,
    int seq_len,
    int num_heads,
    int head_dim_qk,
    int head_dim_v
) {
    // Each block handles one (batch, head) pair
    int batch_idx = blockIdx.x / num_heads;
    int head_idx = blockIdx.x % num_heads;

    if (batch_idx >= batch_size) return;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // State base pointer for this (batch, head)
    int state_base = (batch_idx * num_heads + head_idx) * head_dim_v * head_dim_qk;
    float* S = state + state_base;

    int state_size = head_dim_v * head_dim_qk;

    // Shared memory for k, v, q vectors and S_k intermediate
    extern __shared__ float shared_mem[];
    float* k_shared = shared_mem;                    // [head_dim_qk]
    float* v_shared = k_shared + head_dim_qk;        // [head_dim_v]
    float* q_shared = v_shared + head_dim_v;         // [head_dim_qk]
    float* S_k = q_shared + head_dim_qk;             // [head_dim_v]
    float* error = S_k + head_dim_v;                 // [head_dim_v] - precomputed error

    // Initialize state to zero
    for (int i = tid; i < state_size; i += num_threads) {
        S[i] = 0.0f;
    }
    __syncthreads();

    // Loop over sequence
    for (int t = 0; t < seq_len; t++) {
        // Load k, v, q for this timestep
        int base_qk = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_qk;
        int base_v = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_v;
        int base_gate = (batch_idx * seq_len + t) * num_heads + head_idx;

        // Coalesced loads into shared memory
        for (int i = tid; i < head_dim_qk; i += num_threads) {
            k_shared[i] = k[base_qk + i];
            q_shared[i] = q[base_qk + i];
        }
        for (int i = tid; i < head_dim_v; i += num_threads) {
            v_shared[i] = v[base_v + i];
        }
        __syncthreads();

        float alpha_t = alpha[base_gate];
        float beta_t = beta[base_gate];

        // Step 1: Compute S @ k -> S_k [head_dim_v] and precompute error
        for (int i = tid; i < head_dim_v; i += num_threads) {
            float sum = 0.0f;
            int row_base = i * head_dim_qk;
            #pragma unroll 16
            for (int j = 0; j < head_dim_qk; j++) {
                sum += S[row_base + j] * k_shared[j];
            }
            S_k[i] = sum;
            error[i] = sum - v_shared[i];  // Precompute error = S_k - v
        }
        __syncthreads();

        // Step 2: Update S and compute output simultaneously
        // S_ij = alpha * S_ij - beta * error_i * k_j
        int out_base = ((batch_idx * seq_len + t) * num_heads + head_idx) * head_dim_v;

        for (int i = tid; i < head_dim_v; i += num_threads) {
            float err_i = error[i];
            float beta_err = beta_t * err_i;
            int row_base = i * head_dim_qk;
            float out_sum = 0.0f;

            #pragma unroll 16
            for (int j = 0; j < head_dim_qk; j++) {
                float s_val = S[row_base + j];
                float new_s = alpha_t * s_val - beta_err * k_shared[j];
                S[row_base + j] = new_s;
                out_sum += new_s * q_shared[j];
            }
            output[out_base + i] = out_sum;
        }
        __syncthreads();
    }
}

torch::Tensor gated_deltanet_recurrence(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor alpha,
    torch::Tensor beta
) {
    int batch_size = q.size(0);
    int seq_len = q.size(1);
    int num_heads = q.size(2);
    int head_dim_qk = q.size(3);
    int head_dim_v = v.size(3);

    auto output = torch::zeros({batch_size, seq_len, num_heads, head_dim_v}, 
                               q.options());

    // Allocate state matrix in global memory
    auto state = torch::zeros({batch_size, num_heads, head_dim_v, head_dim_qk},
                              q.options());

    // Ensure contiguous
    q = q.contiguous();
    k = k.contiguous();
    v = v.contiguous();
    alpha = alpha.contiguous();
    beta = beta.contiguous();

    int num_blocks = batch_size * num_heads;
    int threads_per_block = 1024;

    // Shared memory: k + v + q + S_k + error
    int shared_mem_size = (head_dim_qk + head_dim_v + head_dim_qk + head_dim_v + head_dim_v) * sizeof(float);

    hipLaunchKernelGGL(gated_deltanet_recurrence_kernel, 
                       dim3(num_blocks), dim3(threads_per_block), shared_mem_size, 0,
                       q.data_ptr<float>(),
                       k.data_ptr<float>(),
                       v.data_ptr<float>(),
                       alpha.data_ptr<float>(),
                       beta.data_ptr<float>(),
                       output.data_ptr<float>(),
                       state.data_ptr<float>(),
                       batch_size, seq_len, num_heads, head_dim_qk, head_dim_v);

    return output;
}
"""

